#include "so101_gazebo_demo/pick_place/simulation_session_id.hpp"
namespace so101_gazebo_demo::pick_place { SimulationSessionIdResolution resolveSimulationSessionId(RunMode mode,bool resume,std::string id,std::uint64_t ms) { if(resume&&id.empty()) return {std::nullopt,"simulation_session_id is required for resume to reject stale checkpoints"}; if(resume||mode==RunMode::EXECUTE) return {id.empty()?std::optional<std::string>{"execute-"+std::to_string(ms)}:std::optional<std::string>{std::move(id)},""}; return {}; } }
